```1:125:/Users/jace/Documents/newapp/packages/common/common_glasses_protocol/lib/src/protocol/glasses_event.dart
/// Sealed base type for frames received from the glasses device.
sealed class GlassesEvent {
  const GlassesEvent();
}

/// Raw, unparsed device→phone frame.
///
/// Exposes [id], [subId], and [payload] directly so downstream handlers
/// can pattern-match on specific commands without requiring this package
/// to enumerate all subIds upfront.
///
/// ponytail: typed subclasses are added here when a Feature needs them;
/// the raw fallback covers all unknowns.
class GlassesRawEvent extends GlassesEvent {
  /// Creates a raw glasses event.
  GlassesRawEvent({
    required this.id,
    required this.subId,
    required this.payload,
  }) : super();

  /// Command domain identifier (e.g. `0x34` for glasses main domain).
  final int id;

  /// Sub-command identifier.
  final int subId;

  /// Payload bytes after the frame header.
  final List<int> payload;
}

/// Live wearing-state change pushed by the device.
///
/// Native source: Android `OtherAnalyzer.wearStatus()` id=0x34 subId=0x07;
/// payload[0] = 0 (not worn) or 1 (worn).
class GlassesWearStateEvent extends GlassesEvent {
  const GlassesWearStateEvent({required this.isWorn});

  /// `true` when the device detects glasses are physically worn.
  final bool isWorn;
}

/// Battery level notification pushed by the device.
///
/// Native source: Android `CommonAnalyzer` — `0xAB` frame, type byte `0x91`;
/// payload[1] = charging flag (0=no), payload[2] = battery % 0–100.
class GlassesBatteryEvent extends GlassesEvent {
  const GlassesBatteryEvent({
    required this.level,
    required this.isCharging,
  });

  /// Battery percentage 0–100.
  final int level;

  /// Whether the device is currently charging.
  final bool isCharging;
}

/// Device-initiated simultaneous interpretation toggle command.
///
/// Native source: Android `DeviceSimInterAnalyzer` — `0xEA` frame, id=0x46 subId=0x01.
/// Glasses can start/stop interpretation independently (e.g. hardware button).
class GlassesSimInterCommandEvent extends GlassesEvent {
  const GlassesSimInterCommandEvent({
    required this.enable,
    required this.asrLanguageId,
    required this.transLanguageId,
  });

  /// `true` = start interpretation; `false` = stop.
  final bool enable;

  /// ASR source language ID as defined by the 4Paradigm language list API.
  final int asrLanguageId;

  /// Translation target language ID.
  final int transLanguageId;
}

/// Device-initiated recording control during simultaneous interpretation.
///
/// Native source: Android `DeviceSimInterAnalyzer` — `0xEA` frame, id=0x46 subId=0x04.
/// Glasses signal when their microphone starts or stops recording.
class GlassesSimInterRecordEvent extends GlassesEvent {
  const GlassesSimInterRecordEvent({required this.isRecording});

  /// `true` = glasses mic started recording; `false` = stopped.
  final bool isRecording;
}

/// Ack/report for a device operation (photo / audio / video recording).
///
/// Native source: Android `GlassesAnalyzer.handlerDeviceOperation()` id=0x34 subId=0x11.
/// Also covers device-initiated record events on id=0x41 subId=0x01 (same payload layout).
class GlassesDeviceOperationEvent extends GlassesEvent {
  const GlassesDeviceOperationEvent({
    required this.msgType,
    required this.type,
    required this.action,
    required this.result,
    this.reason = 0,
  });

  /// 0 = command ack, 1 = unsolicited device report.
  final int msgType;

  /// 0 = photo, 1 = video, 2 = audio.
  final int type;

  /// 0 = stopped, 1 = started.
  final int action;

  /// 0 = success, 1 = failure.
  final int result;

  /// Failure reason: 0=ok, 1=fail, 2=recording, 3=videoing,
  /// 4=photoing, 5=camera not open (hall), 6=camera error.
  final int reason;

  bool get isAudio => type == 2;
  bool get isStarted => action == 1;
  bool get isSuccess => result == 0;
}
