import 'dart:convert';

import 'glasses_frame.dart';

/// Dart builders for glasses BLE commands. See `native_app/inventory/05-glasses-protocol-map.md`.
class GlassesOrder {
  GlassesOrder._();

  static const glassesId = 0x34;
  static const wifiId = 0x33;

  /// Simultaneous interpretation command domain (0x46).
  static const _simInterId = 0x46;

  /// Device control: photo.
  static const controlTypePhoto = 1;

  /// Device control: audio recording.
  static const controlTypeAudio = 2;

  /// Device control: video recording.
  static const controlTypeVideo = 3;

  /// Recording max duration. [type] 0 = video, 1 = audio.
  static List<int> sendRecordMaxTime({required int type, required int maxTime}) {
    return GlassesFrame.build(
      id: glassesId,
      subId: 0x01,
      payload: [type, maxTime ~/ 256, maxTime % 256],
    );
  }

  /// Key mapping for a physical button.
  static List<int> sendKeyDefine({
    required int keyId,
    required int updateType,
    required int click,
    required int doubleClick,
    required int tripleClick,
    required int longPress2s,
    required int longPress3s,
    required int longPress4s,
    required int longPress5s,
  }) {
    return GlassesFrame.build(
      id: glassesId,
      subId: 0x02,
      payload: [
        keyId,
        updateType,
        click,
        doubleClick,
        tripleClick,
        longPress2s,
        longPress3s,
        longPress4s,
        longPress5s,
      ],
    );
  }

  /// Volume level 0–100.
  static List<int> sendVolume(int volume) {
    return GlassesFrame.build(
      id: glassesId,
      subId: 0x03,
      payload: [volume.clamp(0, 100)],
    );
  }

  /// Voice wakeup on/off.
  static List<int> switchWakeup({required bool isOpen}) {
    return GlassesFrame.build(
      id: glassesId,
      subId: 0x04,
      payload: [isOpen ? 0x01 : 0x00],
    );
  }

  /// WiFi scan on/off.
  static List<int> switchWifiScan({required bool isOpen}) {
    if (isOpen) {
      return GlassesFrame.build(id: wifiId, subId: 0x09, payload: [0x00]);
    }
    // ponytail: 关闭指令 subId=0x0C，与开启的 0x09 不对称，且帧体无 payload 字节，
    // 无法复用 GlassesFrame.build。来源：native_app/inventory/05-glasses-protocol-map.md
    return [0xEA, 0x00, 0x03, 0x00, wifiId, 0x0C];
  }

  /// Device control: [type] uses [controlTypePhoto|Audio|Video]; [action] 0 off, 1 on.
  static List<int> sendDeviceControl({
    required int type,
    required int action,
  }) {
    return GlassesFrame.build(
      id: glassesId,
      subId: 0x11,
      payload: [type, action],
    );
  }

  /// Recording direction. [direction] 0 = landscape, 1 = portrait.
  static List<int> switchDirection({required int direction}) {
    return GlassesFrame.build(
      id: glassesId,
      subId: 0x09,
      payload: [direction],
    );
  }

  /// Hall sensor manual/auto mode.
  static List<int> setHallSwitch({required bool isOpen}) {
    return GlassesFrame.build(
      id: glassesId,
      subId: 0x0F,
      payload: [isOpen ? 0x01 : 0x00],
    );
  }

  /// Auto shutdown query (mode 0) or set (mode 1) with [minute].
  static List<int> setAutoShutdown({required int mode, required int minute}) {
    return GlassesFrame.build(
      id: glassesId,
      subId: 0x10,
      payload: [mode, minute],
    );
  }

  /// WiFi reconnect (no payload).
  ///
  /// ponytail: raw bytes like WiFi scan close — subId 0x0B has no payload,
  /// cannot reuse GlassesFrame.build. Source: 05-glasses-protocol-map.md.
  static List<int> sendWifiReconnect() {
    return [0xEA, 0x00, 0x03, 0x00, wifiId, 0x0B];
  }

  /// Queries the current wear-detection feature switch state.
  ///
  /// Device responds with `0x34/0x0A` — see `OtherAnalyzer.handlerWearSwitch`.
  /// Payload `0x00` = query intent. Source: Android `GlassesOrder.queryWearSwitch`.
  static List<int> queryWearSwitch() {
    return GlassesFrame.build(
      id: glassesId,
      subId: 0x0A,
      payload: [0x00],
    );
  }

  /// Enables or disables the wear-detection feature on the device.
  ///
  /// Device responds with `0x34/0x0A`. Source: Android `GlassesOrder.setWearSwitch`.
  static List<int> setWearSwitch({required bool isOpen}) {
    return GlassesFrame.build(
      id: glassesId,
      subId: 0x0A,
      payload: [0x01, isOpen ? 0x01 : 0x00],
    );
  }

  // ── 0x46 Simultaneous Interpretation ─────────────────────────────────────

  /// Pushes an ASR or translation text result to the glasses display.
  ///
  /// [isStream] streaming partial result; [isAsr] true=ASR text, false=translation.
  /// Native source: `DeviceSimInterOrder.sendDeviceSimInterContent`.
  ///
  /// ponytail: native also fragments by MTU via BleUtil.handleMessageBytes;
  /// upgrade path: split on the sender side when MTU negotiation is exposed.
  static List<int> sendSimInterText({
    required String content,
    required bool isStream,
    required bool isAsr,
  }) {
    final contentBytes = utf8.encode(content);
    final subContent = isStream ? 0x00 : (isAsr ? 0x01 : 0x02);
    // 2-byte big-endian length (like native) so long texts don't overflow.
    final length = contentBytes.length + 4; // 0x00 + id + subId + subContent byte
    return [
      0xEA,
      length >> 8,
      length & 0xFF,
      0x00,
      _simInterId,
      0x03,
      subContent,
      ...contentBytes,
    ];
  }

  /// Sends interpretation status to the glasses.
  ///
  /// status: 0=success, 1=busy, 2=error, 3=timeout, 4=quota exceeded.
  /// Native source: `DeviceSimInterOrder.sendDeviceSimInterState`.
  static List<int> sendSimInterStatus(int statusCode) {
    return GlassesFrame.build(
      id: _simInterId,
      subId: 0x06,
      payload: [statusCode],
    );
  }

  /// Notifies glasses of TTS playback state.
  ///
  /// [isEnd] false=TTS started, true=TTS finished.
  /// Native source: `DeviceSimInterOrder.sendDeviceSimInterTtsState`.
  static List<int> sendSimInterTtsState({required bool isEnd}) {
    return GlassesFrame.build(
      id: _simInterId,
      subId: 0x05,
      payload: [isEnd ? 2 : 1],
    );
  }
}
