/// Re-subscribes automatically when the BLE session reconnects.
/// Yields nothing while disconnected or when the GATT config is incomplete.
///
/// Raw GATT notifications are passed through [GlassesFrameReassembler] before
/// parsing, so callers always receive complete frames regardless of MTU size.
final glassesDeviceEventsProvider = StreamProvider<GlassesEvent>((ref) async* {
  final session = ref.watch(bleSessionProvider);
  if (!session.isConnected) return;

  final connection = ref.read(bleSessionProvider.notifier).connection;
  if (connection == null) return;

  final config = ref.read(glassesTransportConfigProvider);
  if (!config.isConfigured) return;

  final rawFrames = connection
      .notifyCharacteristic(config.serviceUuid, config.notifyCharacteristicUuid)
      .transform(GlassesFrameReassembler());

  await for (final frame in rawFrames) {
    final event = GlassesResponseParser.parse(frame);
    if (event != null) yield event;
  }
});
