/// Single source of truth for glasses device status consumed by Features.
///
/// Watches [bleSessionProvider] for connection state and listens to
/// [glassesDeviceEventsProvider] to back-fill [GlassesDeviceState.isWorn] and
/// [GlassesDeviceState.batteryLevel] from live device Notify events.
final glassesDeviceStateProvider =
    NotifierProvider<GlassesDeviceStateNotifier, GlassesDeviceState>(
  GlassesDeviceStateNotifier.new,
);

/// Notifier backing [glassesDeviceStateProvider].
class GlassesDeviceStateNotifier extends Notifier<GlassesDeviceState> {
  // Accumulated fields stored separately so build() rebuilds (e.g. on deviceName
  // update) don't clobber values already received from device Notify events.
  bool? _isWorn;
  int? _batteryLevel;
  bool? _isCharging;

  @override
  GlassesDeviceState build() {
    final session = ref.watch(bleSessionProvider);

    if (!session.isConnected) {
      // Clear accumulated fields on disconnect.
      _isWorn = null;
      _batteryLevel = null;
      _isCharging = null;
      return GlassesDeviceState(
        isConnected: false,
        deviceId: session.deviceId,
        deviceName: session.deviceName,
      );
    }

    // Wire typed device events → accumulate wear/battery state.
    ref.listen<AsyncValue<GlassesEvent>>(
      glassesDeviceEventsProvider,
      (_, next) => next.whenData(_handleEvent),
    );

    // Preserve already-received device data across build() re-runs.
    return GlassesDeviceState(
      isConnected: true,
      deviceId: session.deviceId,
      deviceName: session.deviceName,
      isWorn: _isWorn,
      batteryLevel: _batteryLevel,
      isCharging: _isCharging,
    );
  }

  void _handleEvent(GlassesEvent event) {
    switch (event) {
      case GlassesWearStateEvent(:final isWorn):
        _isWorn = isWorn;
        state = state.copyWith(isWorn: isWorn);
      case GlassesBatteryEvent(:final level, :final isCharging):
        _batteryLevel = level;
        _isCharging = isCharging;
        state = state.copyWith(batteryLevel: level, isCharging: isCharging);
      default:
        break;
    }
  }
}
