import 'glasses_event.dart';

/// Parses raw BLE Notify bytes into [GlassesEvent]s.
///
/// Two frame families are supported:
///
/// **0xEA — glasses command protocol**
/// ```
/// [0xEA, lenLo, lenHi, 0x00, id, subId, ...payload]
/// ```
/// Typed sub-events derived from (id, subId):
/// - `0x34/0x07` → [GlassesWearStateEvent]
/// - `0x34/0x11` or `0x41/0x01` → [GlassesDeviceOperationEvent]
/// - All others → [GlassesRawEvent]
///
/// **0xAB — legacy device protocol (battery)**
/// ```
/// [0xAB, lenLo, lenHi, 0xFF, typeByte, ?, charge, battery%, ...]
/// ```
/// - type `0x91` → [GlassesBatteryEvent]
///
/// Returns null for unrecognised or malformed frames.
abstract final class GlassesResponseParser {
  static const _eaHeader = 0xEA;
  static const _abHeader = 0xAB;
  static const _eaMinLength = 6;
  static const _abBatteryMinLength = 8;

  static const _glassesId = 0x34;
  static const _deviceInitiatedId = 0x41;
  static const _simInterId = 0x46;
  static const _subIdWearState = 0x07;
  static const _subIdDeviceOp = 0x11;
  static const _abTypeBattery = 0x91;

  /// Parses [frame] into a [GlassesEvent], or returns null if invalid.
  static GlassesEvent? parse(List<int> frame) {
    if (frame.isEmpty) return null;
    return switch (frame[0]) {
      _eaHeader => _parseEa(frame),
      _abHeader => _parseAb(frame),
      _ => null,
    };
  }

  static GlassesEvent? _parseEa(List<int> frame) {
    if (frame.length < _eaMinLength) return null;

    final id = frame[4];
    final subId = frame[5];
    final payload = frame.length > _eaMinLength ? frame.sublist(_eaMinLength) : const <int>[];

    // 0x46/0x01 — device-initiated siminter toggle (start/stop + language IDs)
    if (id == _simInterId && subId == 0x01) {
      if (payload.isEmpty) return null;
      return GlassesSimInterCommandEvent(
        enable: payload[0] == 1,
        asrLanguageId: payload.length > 1 ? payload[1] : 0,
        transLanguageId: payload.length > 2 ? payload[2] : 0,
      );
    }

    // 0x46/0x04 — device recording state change (0=stop, 1=start)
    if (id == _simInterId && subId == 0x04) {
      if (payload.isEmpty) return null;
      return GlassesSimInterRecordEvent(isRecording: payload[0] == 1);
    }

    // 0x34/0x07 — live wear state
    if (id == _glassesId && subId == _subIdWearState && payload.isNotEmpty) {
      return GlassesWearStateEvent(isWorn: payload[0] == 1);
    }

    // 0x34/0x11 — device operation ack (app-initiated)
    // 0x41/0x01 — device-initiated audio record event (same payload layout)
    if ((id == _glassesId && subId == _subIdDeviceOp) ||
        (id == _deviceInitiatedId && subId == 0x01)) {
      if (payload.length >= 3) {
        return GlassesDeviceOperationEvent(
          msgType: payload[0],
          type: payload[1],
          action: payload[2],
          result: payload.length > 3 ? payload[3] : 0,
          reason: payload.length > 4 ? payload[4] : 0,
        );
      }
    }

    return GlassesRawEvent(id: id, subId: subId, payload: payload);
  }

  static GlassesEvent? _parseAb(List<int> frame) {
    if (frame.length < _abBatteryMinLength) return null;
    // 0xAB layout: [0xAB, lenLo, lenHi, 0xFF, typeByte, ?, charge, battery%]
    final typeByte = frame[4];
    if (typeByte != _abTypeBattery) return null;

    final isCharging = frame[6] != 0;
    final level = frame[7].clamp(0, 100);
    return GlassesBatteryEvent(level: level, isCharging: isCharging);
  }
}
