/// Glasses 0xEA frame builder utilities.
class GlassesFrame {
  GlassesFrame._();

  /// Builds a standard glasses command frame.
  ///
  /// Length byte matches native `GlassesOrder`: ID + subId + payload + 1.
  static List<int> build({
    required int id,
    required int subId,
    List<int> payload = const [],
  }) {
    final length = payload.length + 3;
    return [
      0xEA,
      0x00,
      length,
      0x00,
      id,
      subId,
      ...payload,
    ];
  }
}
